iiActorObject::TemplateAdaptOptions options;
options.rig.projection.registration = iiActorObject::TemplateRigRegistration::AxisAlignedBounds;
options.rig.shapeFit.enabled = true;
options.publishMorphs = true; // 외부 형식의 원본 타깃 모프 채널도 필요할 때
auto adapted = sourceCharacterTemplate.adaptMesh(staticMesh, options);
iiActorObject::NSCharacter::CharacterTemplate character(adapted.program);
auto baseline = character.generate(adapted.report.baselineValues);
auto editor = character.edit(adapted.report.baselineValues);
// editor.setTemplateValues(...)로 원래 템플릿의 조절값을 설정한다.
```

